    @Override public void onCreate(){super.onCreate();prefs=getSharedPreferences("smarthub",MODE_PRIVATE);windows=(WindowManager)getSystemService(WINDOW_SERVICE);guide=new SatelliteGuideRepository(this);publishedArtwork=new PublishedEpgArtwork(this);factory=new FactoryProvider(this);dvb=new ReceiverDvbBridge(this);directSignal=ReceiverInfoRepository.get(this).acquireSignal();media=new MediaRepository(this);NotificationChannel notificationChannel=new NotificationChannel(CHANNEL,"Live satellite assistant",NotificationManager.IMPORTANCE_LOW);getSystemService(NotificationManager.class).createNotificationChannel(notificationChannel);}
    @Override public int onStartCommand(Intent intent,int flags,int startId){
        if(intent==null){stopSelf();return START_NOT_STICKY;}
        foreground();
        if(ACTION_STOP.equals(intent.getAction())){stopSelf();return START_NOT_STICKY;}
        if(!Settings.canDrawOverlays(this)){prefs.edit().putString("satellite_companion_error","Display-over-apps permission is required").putBoolean("satellite_companion_enabled",false).apply();stopSelf();return START_NOT_STICKY;}
        prefs.edit().putBoolean("satellite_companion_enabled",true).putBoolean("satellite_companion_running",true).putString("satellite_companion_error","").apply();
        if(!pollStarted){pollStarted=true;poller.scheduleWithFixedDelay(this::poll,0,1,TimeUnit.SECONDS);}
        if(ACTION_OPEN.equals(intent.getAction())){expanded=true;openGrace=SystemClock.elapsedRealtime()+2500;prefs.edit().putBoolean("satellite_companion_expanded",true).apply();rebuild();}
        else if(ACTION_INFO.equals(intent.getAction())){syncOnly=false;expanded=false;openGrace=SystemClock.elapsedRealtime()+2500;bannerTime.show(SystemClock.elapsedRealtime());prefs.edit().putBoolean("satellite_companion_expanded",false).apply();rebuild();}
        else if(overlay==null&&prefs.getBoolean("satellite_tv_visible",false))rebuild();
        return START_NOT_STICKY;
    }
